/* Numerical engine: standardized Euclidean distances, Lloyd and DBSCAN. */
const Engine=(()=>{
const d2=(a,b)=>a.reduce((s,v,j)=>s+(v-b[j])**2,0);
function standardize(x){const n=x.length,p=x[0].length,mean=Array.from({length:p},(_,j)=>x.reduce((s,r)=>s+r[j],0)/n),scale=mean.map((v,j)=>Math.sqrt(x.reduce((s,r)=>s+(r[j]-v)**2,0)/n)||1);return {mean,scale,z:x.map(r=>r.map((v,j)=>(v-mean[j])/scale[j]))};}
function kmeans(z,k){let best=null;for(let restart=0;restart<20;restart++){let centers=[z[(restart*13+7)%z.length].slice()];while(centers.length<k){let index=0,max=-1;z.forEach((r,i)=>{const dist=Math.min(...centers.map(c=>d2(r,c)));if(dist>max){max=dist;index=i;}});centers.push(z[index].slice());}let labels=[],iterations=0;for(;iterations<200;iterations++){const next=z.map(r=>centers.map(c=>d2(r,c)).reduce((bi,v,j,a)=>v<a[bi]?j:bi,0));const stable=next.every((v,i)=>v===labels[i]);labels=next;centers=centers.map((c,g)=>{let rows=z.filter((_,i)=>labels[i]===g);return rows.length?c.map((_,j)=>rows.reduce((s,r)=>s+r[j],0)/rows.length):c;});if(stable)break;}const inertia=z.reduce((s,r,i)=>s+d2(r,centers[labels[i]]),0);if(!best||inertia<best.inertia)best={labels,centers,inertia,iterations:iterations+1};}return best;}
function dbscan(z,eps,minpts){const labels=Array(z.length).fill(-2),near=i=>z.map((r,j)=>d2(z[i],r)<=eps*eps+1e-12?j:-1).filter(j=>j>=0);let g=0;for(let i=0;i<z.length;i++){if(labels[i]!==-2)continue;let seeds=near(i);if(seeds.length<minpts){labels[i]=-1;continue;}labels[i]=g;let queue=seeds.slice(),seen=new Set(seeds);for(let at=0;at<queue.length;at++){const j=queue[at];if(labels[j]===-1)labels[j]=g;if(labels[j]!==-2)continue;labels[j]=g;const n=near(j);if(n.length>=minpts)n.forEach(v=>{if(!seen.has(v)){queue.push(v);seen.add(v);}});}g++;}return {labels};}
function silhouette(z,labels){const groups=[...new Set(labels.filter(g=>g>=0))];const ids=labels.map((g,i)=>g>=0?i:-1).filter(i=>i>=0);if(groups.length<2||groups.length>=ids.length)return null;let total=0;for(const i of ids){const own=ids.filter(j=>labels[j]===labels[i]&&j!==i);if(!own.length)continue;const a=own.reduce((s,j)=>s+Math.sqrt(d2(z[i],z[j])),0)/own.length;let b=Infinity;groups.filter(g=>g!==labels[i]).forEach(g=>{const other=ids.filter(j=>labels[j]===g);b=Math.min(b,other.reduce((s,j)=>s+Math.sqrt(d2(z[i],z[j])),0)/other.length);});total+=(b-a)/Math.max(a,b)||0;}return total/ids.length;}
function parseCSV(text,features){text=text.replace(/^\uFEFF/,'');const lines=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else if(!field||quoted)quoted=!quoted;else throw Error('Comillas CSV inválidas.');}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))lines.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('Hay comillas sin cerrar.');row.push(field);if(row.some(v=>v.trim()))lines.push(row);if(lines.length<2)throw Error('El archivo no contiene filas de datos.');const h=lines.shift().map(s=>s.trim());if(new Set(h).size!==h.length)throw Error('Hay nombres de columnas repetidos.');for(const f of ['Sample_ID',...features])if(!h.includes(f))throw Error('Falta la columna '+f+'. Usa la plantilla.');if(lines.length<8||lines.length>500)throw Error('Se requieren entre 8 y 500 muestras.');const ids=new Set();return lines.map((r,i)=>{if(r.length!==h.length)throw Error('Número de columnas incorrecto en fila '+(i+2));const o=Object.fromEntries(h.map((v,j)=>[v,r[j].trim()]));if(!o.Sample_ID||ids.has(o.Sample_ID))throw Error('Los IDs deben existir y ser únicos (fila '+(i+2)+').');ids.add(o.Sample_ID);const out={Sample_ID:o.Sample_ID};for(const f of features){if(!o[f]||!Number.isFinite(Number(o[f])))throw Error('Valor numérico incompleto o inválido en '+f+', fila '+(i+2));const v=Number(o[f]);if(v<0||(f==='pH'&&v>14)||((f.endsWith('_pct'))&&v>100))throw Error('Valor fuera de rango físico en '+f+', fila '+(i+2));out[f]=v;}if(out.Sand_pct+out.Clay_pct>100.1)throw Error('Arena + arcilla supera 100% en fila '+(i+2));return out;});}
return {d2,standardize,kmeans,dbscan,silhouette,parseCSV};})();
if(typeof module!=='undefined')module.exports=Engine;
